#[derive(Clone, PartialEq)]
enum State { Idle, Busy, Failed(String) }
enum Event { Submit, Failed(String) }
fn reduce(state: &State, ev: Event) -> State {
    match (state, ev) {
        (State::Idle, Event::Submit) => State::Busy,
        (State::Busy, Event::Failed(r)) => State::Failed(r),
        (s, _) => s.clone(),
    }
}
